class Processor:
    def __init__(self, window):
        self.window = window
        self.effects = []
        self._seen = {}  # key -> (result, recorded_at)

    def process(self, key, payload, now):
        cached = self._seen.get(key)
        if cached is not None:
            result, recorded_at = cached
            if now - recorded_at < self.window:
                return result
        self.effects.append((key, payload))
        result = {"key": key, "payload": payload, "processed_at": now}
        self._seen[key] = (result, now)
        return result

